import re,glob,collections
tbl={}
for line in open('draft/numerals.md'):
    m=re.match(r'\|\s*(\d+)\s*\|\s*([^|]+?)\s*\|',line)
    if m: tbl[m.group(1)]=m.group(2)
print(tbl)
for f in sorted(glob.glob('draft/*.md'))+sorted(glob.glob('figures/*.md')):
    txt=open(f).read()
    nums=set(re.findall(r'(?<![\d/.-])(\d{2})(?![\d/])',txt))
    unknown=nums-set(tbl)
    if unknown: print(f,'UNKNOWN',sorted(unknown))
# abstract word count
a=open('draft/10-abstract.md').read().split()
print('abstract words',len(a))
for f in sorted(glob.glob('figures/*.md')):
    print(f, len(open(f).read()))
